<script setup lang="ts">
import type { AuditMetric } from '#shared/utils/seosmith'
import { auditMetricLabels, safeAuditUrl, comparable, findingChanges } from '#shared/utils/seosmith'
import type { AuditDetail, AuditPage } from '../../shared/types/seosmith'
import { lifecycleHistory } from '#shared/utils/seosmith-lifecycle'
import type { LifecycleComparison } from '#shared/utils/seosmith-lifecycle'
import { indexedTransitions, type IndexedHistoryRow } from '#shared/utils/seosmith-indexed-history'
import { urlHistoryDeltas, type UrlHistoryRow } from '#shared/utils/seosmith-url-history'
const ws = useWorkspace()
const indexedHistoryEnabled = useRuntimeConfig().public.rolloutLifecycle === true
const { runs, selected, busy, detailBusy, importing, error, notice, cursor, load, select, importFile } = useSeosmith()
const urlPage = ref(1), urlSearch = ref(''), urlStatus = ref('all')
const metric = ref<AuditMetric>('findings'), severity = ref('all'), rule = ref('all'), search = ref(''), page = ref(1)
const fileInput = ref<HTMLInputElement | null>(null), comparisonBusy = ref(false), comparisonError = ref('')
const lifecycle = ref<LifecycleComparison | null>(null)
const lifecycleDepth = ref(0)
const findingHistory = ref<{ items: IndexedHistoryRow[]; has_more: boolean; next_cursor: { before: string; before_id: string } | null } | null>(null)
const historySelection = ref<{ entity_id: string; rule: string } | null>(null)
const historyBusy = ref(false), historyError = ref('')
const urlHistory = ref<{ items: UrlHistoryRow[]; has_more: boolean; next_cursor: { before: string; before_id: string } | null } | null>(null)
const urlHistorySelection = ref<{ entity_id: string; url: string } | null>(null)
const urlHistoryBusy = ref(false), urlHistoryError = ref('')
let urlHistoryGeneration = 0
const urlDeltas = computed(() => urlHistory.value ? urlHistoryDeltas(urlHistory.value.items) : [])
const observationIds = computed(() => { const result = new Map<AuditPage,string>(); const report=selected.value?.report; if (!report || report.schema_version !== 2 || report.evidence_contract?.version !== 1) return result; for (const o of report.evidence_contract.observations) { const m=o.source_locator.match(/^\/pages\/(0|[1-9][0-9]*)$/); const p=m ? report.pages[Number(m[1])] : undefined; if (p) result.set(p,o.entity_id) } return result })
const historyTransitions = computed(() => findingHistory.value ? indexedTransitions(findingHistory.value.items, findingHistory.value.has_more) : [])
const historyFailures = computed(() => findingHistory.value?.items.filter(item => item.evidence_state === 'evaluated' && item.evaluation?.outcome === 'fail') ?? [])
let historyGeneration = 0
const baselineId = ref('')
const changes = ref<{ added: number; resolved: number; persistent: number; unverified: number } | null>(null)
let comparisonGeneration = 0
const summary = computed(() => selected.value?.summary)
const findings = computed(() => selected.value?.report.findings ?? [])
const findingEvaluations = computed(() => { const result = new Map<string,{entity_id:string;rule:string}>(); const report=selected.value?.report; if (report?.schema_version !== 2 || report.evidence_contract?.version !== 1) return result; for (const evaluation of report.evidence_contract.evaluations) if (evaluation.finding_key) result.set(evaluation.finding_key,{entity_id:evaluation.entity_id,rule:evaluation.rule}); return result })
const ruleOptions = computed(() => [...new Set(findings.value.map(f => f.rule))].sort())
const filtered = computed(() => findings.value.filter(f => (severity.value === 'all' || f.severity === severity.value) && (rule.value === 'all' || f.rule === rule.value) && `${f.url} ${f.rule} ${f.evidence}`.toLowerCase().includes(search.value.toLowerCase())).sort((a, b) => ['critical', 'alert', 'warning'].indexOf(a.severity) - ['critical', 'alert', 'warning'].indexOf(b.severity) || a.url.localeCompare(b.url)))
const displayed = computed(() => filtered.value.slice((page.value - 1) * 50, page.value * 50))
const pages = computed(() => (selected.value?.report.pages ?? []).filter(p => p.url.toLowerCase().includes(urlSearch.value.toLowerCase()) && (urlStatus.value === 'all' || (urlStatus.value === 'errors' ? (p.status !== null && p.status >= 400) || !!p.error : p.content_type.startsWith(urlStatus.value)))))
const baselineOptions = computed(() => { const index = runs.value.findIndex(r => r.delivery_id === selected.value?.delivery_id); return index >= 0 ? runs.value.slice(index + 1, index + 10) : [] })
const previous = computed(() => baselineOptions.value.find(r => r.delivery_id === baselineId.value) || baselineOptions.value[0])
const canCompare = computed(() => {
  const a = selected.value, b = previous.value
  return !!(a && b && (comparable(a, b) || (a.summary.schema_version === 2 && b.summary.schema_version === 2 && !!a.summary.comparison_key && a.summary.comparison_key === b.summary.comparison_key && !!a.summary.engine_version && a.summary.engine_version === b.summary.engine_version && !!a.summary.ruleset_version && a.summary.ruleset_version === b.summary.ruleset_version)))
})
watch(() => [selected.value?.delivery_id, urlSearch.value, urlStatus.value], () => { urlPage.value = 1 })
watch(() => [selected.value?.delivery_id, severity.value, rule.value, search.value], () => { page.value = 1 })
watch(() => selected.value?.delivery_id, () => { rule.value = 'all'; urlHistoryGeneration++; urlHistory.value = null; urlHistorySelection.value = null; urlHistoryError.value = ''; urlHistoryBusy.value = false; historyGeneration++; findingHistory.value = null; historySelection.value = null; historyError.value = ''; historyBusy.value = false; baselineId.value = ''; changes.value = null; lifecycle.value = null; comparisonError.value = ''; comparisonGeneration++; comparisonBusy.value = false })
onBeforeUnmount(() => { comparisonGeneration++; historyGeneration++; urlHistoryGeneration++ })
function stamp(value: string) { return new Date(value).toISOString().replace('T', ' ').slice(0, 19) + ' UTC' }
function label(value: string) { return value.replaceAll('_', ' ') }
function displayEvidence(value: unknown) { const text = JSON.stringify(value) ?? 'Unavailable'; return text.length > 500 ? text.slice(0, 500) + '… (truncated; see source report)' : text }
async function upload(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; if (file) await importFile(file); input.value = '' }
async function compareRuns() {
  if (!selected.value || !previous.value || !canCompare.value) return
  const current = selected.value, older = previous.value, gen = ++comparisonGeneration
  comparisonBusy.value = true; comparisonError.value = ''
  try {
    const detail = await ws.request<AuditDetail>(`/api/websites/${ws.selectedId.value}/seo/audits/${older.delivery_id}`)
    const selectedIndex = runs.value.findIndex(r => r.delivery_id === current.delivery_id)
    const earlier = current.summary.schema_version === 2 ? runs.value.slice(selectedIndex + 1, selectedIndex + 10) : []
    const history: AuditDetail[] = []
    // Stop at the first incompatible report; do not bridge gaps in comparable history.
    for (const run of earlier) {
      if (run.summary.schema_version !== 2 || run.summary.comparison_key !== current.summary.comparison_key || run.summary.engine_version !== current.summary.engine_version || run.summary.ruleset_version !== current.summary.ruleset_version) break
      history.unshift(run.delivery_id === older.delivery_id ? detail : await ws.request<AuditDetail>(`/api/websites/${ws.selectedId.value}/seo/audits/${run.delivery_id}`))
    }
    if (gen === comparisonGeneration) {
      const historyComplete = !cursor.value && history.length === runs.value.length - selectedIndex - 1
      lifecycle.value = lifecycleHistory([...history, current], older.delivery_id, historyComplete)
      lifecycleDepth.value = history.length + 1
      changes.value = lifecycle.value || current.summary.schema_version !== 1 || older.summary.schema_version !== 1 ? null : findingChanges(current, older, current.report.findings, detail.report.findings, current.report.pages)
      if (!lifecycle.value && !changes.value) comparisonError.value = 'These reports do not have compatible comparison evidence.'
    }
  } catch (cause) { if (gen === comparisonGeneration) comparisonError.value = failureMessage(cause) }
  finally { if (gen === comparisonGeneration) comparisonBusy.value = false }
}
async function loadFindingHistory(entity_id: string, rule: string, more = false) {
  const gen = ++historyGeneration
  if (!more) { findingHistory.value = null; historySelection.value = { entity_id, rule } }
  const cursor = more ? findingHistory.value?.next_cursor : null
  historyBusy.value = true; historyError.value = ''
  try {
    const result = await ws.request<NonNullable<typeof findingHistory.value>>(`/api/websites/${ws.selectedId.value}/seo/audits/lifecycle`, { query: { entity_id, rule, limit: 50, ...(cursor ?? {}) } })
    if (gen === historyGeneration) findingHistory.value = { ...result, items: [...(more ? findingHistory.value?.items.slice(-1) ?? [] : []), ...result.items] }
  } catch (cause) { if (gen === historyGeneration) historyError.value = failureMessage(cause) }
  finally { if (gen === historyGeneration) historyBusy.value = false }
}
async function loadUrlHistory(entity_id: string, url: string, more = false) {
  const gen = ++urlHistoryGeneration
  if (!more) { urlHistory.value = null; urlHistorySelection.value = { entity_id, url } }
  const cursor = more ? urlHistory.value?.next_cursor : null
  urlHistoryBusy.value = true; urlHistoryError.value = ''
  try {
    const result = await ws.request<NonNullable<typeof urlHistory.value>>(`/api/websites/${ws.selectedId.value}/seo/audits/url-lifecycle`, { query: { entity_id, limit: 50, ...(cursor ?? {}) } })
    if (gen === urlHistoryGeneration) urlHistory.value = { ...result, items: [...(more ? urlHistory.value?.items.slice(-1) ?? [] : []), ...result.items] }
  } catch (cause) { if (gen === urlHistoryGeneration) urlHistoryError.value = failureMessage(cause) }
  finally { if (gen === urlHistoryGeneration) urlHistoryBusy.value = false }
}
function download() {
  if (!selected.value) return
  const url = URL.createObjectURL(new Blob([selected.value.report_json || JSON.stringify(selected.value.report, null, 2)], { type: 'application/json' }))
  const a = document.createElement('a'); a.href = url; a.download = `seosmith-${selected.value.delivery_id}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
}
</script>
<template>
  <section class="insight-section seosmith-section" aria-labelledby="seosmith-title" :aria-busy="busy">
    <div class="analytics-section-heading"><div><h2 id="seosmith-title">Technical SEO · Seosmith</h2><p>Every saved crawl, its findings, and how the site changes over time.</p></div><div v-if="ws.user.value && ws.selected.value" class="seo-actions"><button class="refresh-control" :disabled="busy || importing" @click="load()">Refresh audits</button><button class="refresh-control" :disabled="importing" @click="fileInput?.click()">{{ importing ? 'Saving run…' : 'Import JSON report' }}</button><input ref="fileInput" class="sr-only" type="file" accept="application/json,.json" aria-label="Import Seosmith JSON report" @change="upload" /></div></div>
    <p v-if="error" role="alert" class="form-error">{{ error }} <button @click="load()">Try again</button></p>
    <p v-if="notice" role="status" class="form-notice">{{ notice }}</p>
    <div v-if="!runs.length" class="report-panel chart-empty" aria-live="polite"><UIcon name="i-lucide-scan-search" /><h3>{{ !ws.user.value ? 'Sign in to see technical audits.' : !ws.selected.value ? 'Select a website for technical audits.' : busy ? 'Reading saved audits…' : error ? 'Audits could not load.' : 'No Seosmith runs saved yet.' }}</h3><p>Import a JSON report for this exact hostname, or connect a Seosmith worker. Every run is retained independently of Google and Bing.</p></div>
    <template v-else>
      <div class="report-panel seo-trend-panel"><header><div><h3>Audit history</h3><p class="report-caption">All dates · {{ runs.length }} runs loaded{{ cursor ? ' · more history available' : '' }}</p></div><label class="insight-control">Plot<select v-model="metric" aria-label="Audit chart metric"><option v-for="(text, key) in auditMetricLabels" :key="key" :value="key">{{ text }}</option></select></label></header><SeosmithTrend :runs="runs" :metric="metric" :selected-id="selected?.delivery_id" @select="select" /></div>
      <div class="seo-run-picker"><label>Inspect a run<select aria-label="Inspect a run" :value="selected?.delivery_id || ''" :disabled="detailBusy" @change="select(($event.target as HTMLSelectElement).value)"><option v-if="detailBusy" value="">Loading run…</option><option v-for="run in runs" :key="run.delivery_id" :value="run.delivery_id">{{ stamp(run.scan_at) }}{{ !run.summary.finished_at ? ' (receipt time)' : '' }} · {{ run.summary.outcome }} · {{ run.summary.pages.checked }} URLs · {{ run.summary.findings }} findings</option></select></label><button v-if="cursor" class="refresh-control" :disabled="busy" @click="load(true)">Load older runs</button></div>
      <p v-if="detailBusy" role="status" class="compact-empty">Loading this run’s findings…</p>
      <template v-if="selected && summary">
        <div class="insight-totals seo-summary"><div><span>URLs checked</span><strong>{{ summary.pages.checked.toLocaleString() }}</strong></div><div><span>Critical</span><strong>{{ summary.severities.critical.toLocaleString() }}</strong></div><div><span>Alerts</span><strong>{{ summary.severities.alert.toLocaleString() }}</strong></div><div><span>Warnings</span><strong>{{ summary.severities.warning.toLocaleString() }}</strong></div><div><span>HTTP errors</span><strong>{{ summary.pages.http_errors.toLocaleString() }}</strong></div></div>
        <p v-if="summary.coverage_complete === false" class="form-notice" role="status">This run has incomplete coverage: {{ label(summary.stop_reason || summary.outcome) }}. Missing findings do not mean issues were fixed.</p>
        <p v-else-if="summary.coverage_complete == null" class="form-notice" role="status">Coverage for this run is unknown. Missing findings do not mean issues were fixed.</p>
        <p class="report-caption">{{ stamp(selected.scan_at) }} · {{ summary.outcome }} · {{ summary.pages.html }} successful HTML pages · {{ summary.pages.images }} images · {{ summary.pages.fetch_errors }} fetch errors.<span>Engine {{ summary.engine_version || 'unknown' }} · Ruleset {{ summary.ruleset_version || 'unknown' }} · {{ selected.report.request.max_pages }}-URL cap · {{ selected.ingestion_source === 'import' ? 'Imported report' : 'Worker delivery' }} · Received {{ stamp(selected.received_at) }}.</span></p>
        <AuditCoverage :audit="selected" />
        <SeosmithRemediation v-if="useRuntimeConfig().public.rolloutRemediation === true" :audit="selected" />
        <div class="seo-actions"><button class="refresh-control" @click="download">Download run JSON</button><label v-if="baselineOptions.length">Baseline <select v-model="baselineId" aria-label="Comparison baseline" @change="changes = null; lifecycle = null; comparisonError = ''; comparisonGeneration++; comparisonBusy = false"><option value="">Previous run</option><option v-for="run in baselineOptions" :key="run.delivery_id" :value="run.delivery_id">{{ stamp(run.scan_at) }} · {{ run.delivery_id }}</option></select></label><button v-if="canCompare" class="refresh-control" :disabled="comparisonBusy" @click="compareRuns">{{ comparisonBusy ? 'Comparing…' : 'Compare findings with baseline' }}</button></div>
        <p v-if="previous && !canCompare" class="report-caption">Finding changes are unavailable against the selected baseline because coverage or crawl settings, engine, or ruleset differ. Both observations remain in the chart.</p>
        <p v-if="lifecycle" class="form-notice" role="status">Compared with baseline {{ lifecycle.baseline_id }}: {{ lifecycle.entries.filter(e => e.state === 'new').length }} new · {{ lifecycle.entries.filter(e => e.state === 'resolved').length }} resolved · {{ lifecycle.entries.filter(e => e.state === 'persisting').length }} persisting · {{ lifecycle.entries.filter(e => e.state === 'changed').length }} changed · {{ lifecycle.entries.filter(e => e.state === 'reopened').length }} reopened · {{ lifecycle.entries.filter(e => e.state === 'not_observed').length }} not observed. Only explicit comparable evaluations establish transitions; missing or unknown checks remain unverified.</p>
        <details v-if="lifecycle" class="seo-history-table"><summary>Finding lifecycle and rule coverage</summary><p class="report-caption">First and last observed times and reopenings are limited to {{ lifecycleDepth }} loaded compatible runs, including this run. New and reopened states require sufficient earlier evidence; incomplete history remains not observed. Coverage denominators count stored observations, not the entire site.</p><div class="table-scroll"><table><thead><tr><th>Rule</th><th>State</th><th>URL</th><th>First observed</th><th>Last observed</th><th>Evidence run</th><th>Saved history</th></tr></thead><tbody><tr v-for="entry in lifecycle.entries" :key="entry.entity_id + entry.rule"><td>{{ label(entry.rule) }}</td><td>{{ label(entry.state) }}</td><td>{{ entry.finding?.url || entry.entity_id }}</td><td>{{ stamp(entry.first_observed) }}</td><td>{{ stamp(entry.last_observed) }}</td><td>{{ entry.source_delivery_id }} · {{ entry.source_locator }}</td><td><button v-if="indexedHistoryEnabled" class="refresh-control" :disabled="historyBusy" @click="loadFindingHistory(entry.entity_id, entry.rule)">Read history</button></td></tr></tbody></table></div><details><summary>URL changes and unavailable observations ({{ lifecycle.urls.length }})</summary><p class="report-caption">Only observed properties present in both reports are compared. A missing URL or unavailable observation is not evidence of removal. Showing at most 100 entries.</p><div class="table-scroll"><table><thead><tr><th>URL</th><th>State</th><th>Changed properties</th><th>Source pointers (baseline / current)</th></tr></thead><tbody><tr v-for="item in lifecycle.urls.slice(0, 100)" :key="item.entity_id"><td>{{ item.url }}</td><td>{{ label(item.state) }}</td><td><span v-if="!item.properties.length">Unavailable</span><ul v-else><li v-for="property in item.properties" :key="property.property">{{ property.property }}: {{ displayEvidence(property.before) }} → {{ displayEvidence(property.current) }}</li></ul></td><td>{{ item.baseline_locator || 'Unavailable' }} / {{ item.current_locator || 'Unavailable' }}</td></tr></tbody></table></div></details><details><summary>Per-rule coverage</summary><div class="table-scroll"><table><thead><tr><th>Rule</th><th>Stored entities</th><th>Attempted</th><th>Not attempted</th><th>Attempt unknown</th><th>Unknown outcomes</th><th>Ineligible or eligibility unknown</th></tr></thead><tbody><tr v-for="coverage in lifecycle.coverage" :key="coverage.rule"><td>{{ label(coverage.rule) }}</td><td>{{ coverage.entities }}</td><td>{{ coverage.attempted }}</td><td>{{ coverage.not_attempted ?? 'Unavailable' }}</td><td>{{ coverage.attempt_unknown ?? 'Unavailable' }}</td><td>{{ coverage.unknown }}</td><td>{{ coverage.excluded }}</td></tr></tbody></table></div></details></details>
        <section v-if="historySelection" class="report-panel" aria-label="Finding history"><p v-if="historyError" role="alert" class="form-error">{{ historyError }}</p><div v-if="historySelection"><h4>Saved history · {{ label(historySelection.rule) }}</h4><p class="report-caption">Each page shows up to 50 runs and retains one boundary row. Pending, omitted, legacy and unsupported records cannot establish a pass. Source pointers refer to the saved run.</p><p v-if="historyBusy" role="status">Loading history…</p><div v-if="findingHistory" class="table-scroll"><p v-if="historyFailures.length" class="report-caption">Observed failures in loaded rows: first {{ stamp(historyFailures[historyFailures.length - 1]!.scan_at) }} · last {{ stamp(historyFailures[0]!.scan_at) }}. {{ findingHistory.has_more ? 'Older history remains; these bounds may change.' : 'No older page remains; pending or unknown evidence may still hide earlier observations.' }}</p><table><thead><tr><th>Scan</th><th>Delivery</th><th>Source</th><th>Evidence state</th><th>Outcome</th><th>Transition from prior run</th><th>Source pointer</th></tr></thead><tbody><tr v-for="(item, historyIndex) in findingHistory.items" :key="item.delivery_id"><td>{{ stamp(item.scan_at) }}</td><td>{{ item.delivery_id }}</td><td>{{ item.ingestion_source === 'import' ? 'Imported report' : item.ingestion_source === 'worker' ? 'Worker delivery' : 'Unavailable' }}</td><td>{{ label(item.evidence_state) }}</td><td>{{ item.evaluation?.outcome || 'Unknown' }}</td><td>{{ label(historyTransitions[historyIndex] || 'not_observed') }}</td><td>{{ item.evaluation?.source_locator || 'Unavailable' }}</td></tr></tbody></table><button v-if="findingHistory.has_more" class="refresh-control" :disabled="historyBusy" @click="loadFindingHistory(historySelection.entity_id, historySelection.rule, true)">Load older history</button></div></div></section>
        <p v-if="changes" class="form-notice" role="status">Compared with the selected complete baseline: {{ changes.added }} new · {{ changes.resolved }} resolved · {{ changes.persistent }} persistent findings.<span v-if="changes.unverified">{{ ' ' }}{{ changes.unverified }} could not be verified from the current observations.</span></p><p v-if="comparisonError" class="form-error" role="alert">{{ comparisonError }}</p>
        <div class="report-panel seo-findings"><header><h3>Findings</h3><span>{{ filtered.length.toLocaleString() }} matching</span></header><div class="seo-filters"><label>Severity<select v-model="severity" aria-label="Severity"><option value="all">All severities</option><option value="critical">Critical</option><option value="alert">Alerts</option><option value="warning">Warnings</option></select></label><label>Rule<select v-model="rule" aria-label="Rule"><option value="all">All rules</option><option v-for="id in ruleOptions" :key="id" :value="id">{{ label(id) }}</option></select></label><label>Find a URL or issue<input v-model="search" type="search" placeholder="Search findings" /></label></div>
          <div class="table-scroll"><table><caption class="sr-only">Seosmith findings for the selected run</caption><thead><tr><th scope="col">Severity</th><th scope="col">Finding</th><th scope="col">Affected URL</th><th scope="col">Evidence</th><th scope="col">History</th></tr></thead><tbody><tr v-for="(finding, index) in displayed" :key="`${finding.key}-${index}`"><td><span class="seo-severity" :class="`seo-${finding.severity}`">{{ finding.severity }}</span></td><td>{{ label(finding.rule) }}</td><td><a v-if="safeAuditUrl(finding.url)" :href="safeAuditUrl(finding.url)" target="_blank" rel="noopener noreferrer">{{ finding.url }}</a><span v-else>{{ finding.url }}</span></td><td>{{ finding.evidence }}</td><td><button v-if="indexedHistoryEnabled && findingEvaluations.has(finding.key)" class="refresh-control" :disabled="historyBusy" @click="loadFindingHistory(findingEvaluations.get(finding.key)!.entity_id, findingEvaluations.get(finding.key)!.rule)">Read finding history</button><span v-else>Unavailable</span></td></tr></tbody></table></div><p v-if="!filtered.length" class="compact-empty">No findings match these filters.</p><div v-if="filtered.length > 50" class="seo-pagination"><button class="refresh-control" :disabled="page === 1" @click="page--">Previous findings</button><span>Page {{ page }} of {{ Math.ceil(filtered.length / 50) }}</span><button class="refresh-control" :disabled="page * 50 >= filtered.length" @click="page++">Next findings</button></div>
        </div>
        <details class="seo-pages seo-history-table"><summary>URLs checked in this run ({{ selected.report.pages.length }})</summary><div class="seo-filters"><label>Resource type<select v-model="urlStatus" aria-label="Resource type"><option value="all">All resources</option><option value="errors">HTTP / fetch errors</option><option value="text/html">HTML</option><option value="image/">Images</option></select></label><label>Find a checked URL<input v-model="urlSearch" type="search" placeholder="Search checked URLs" /></label></div><div class="table-scroll"><table><thead><tr><th>URL</th><th>Status</th><th>Title / type</th><th>Size (KiB)</th><th>Headers (ms)</th><th>History</th></tr></thead><tbody><tr v-for="(item, index) in pages.slice((urlPage - 1) * 50, urlPage * 50)" :key="`${item.url}-${index}`"><td><a v-if="safeAuditUrl(item.url)" :href="safeAuditUrl(item.url)" target="_blank" rel="noopener noreferrer">{{ item.url }}</a><span v-else>{{ item.url }}</span></td><td>{{ item.error ? 'Fetch failed' : item.blocked_by_robots ? 'Robots blocked' : item.status ?? 'Unavailable' }}</td><td>{{ item.title || item.content_type || 'Unavailable' }}</td><td>{{ (item.bytes / 1024).toFixed(1) }}</td><td>{{ item.status === null ? '—' : item.ttfb_ms }}</td><td><button v-if="indexedHistoryEnabled && observationIds.has(item)" class="refresh-control" :disabled="urlHistoryBusy" @click="loadUrlHistory(observationIds.get(item)!, item.url)">Read URL history</button><span v-else>Unavailable</span></td></tr></tbody></table></div><p v-if="!pages.length" class="compact-empty">No checked URLs match these filters.</p><div v-if="pages.length > 50" class="seo-pagination"><button class="refresh-control" :disabled="urlPage === 1" @click="urlPage--">Previous URLs</button><span>Page {{ urlPage }} of {{ Math.ceil(pages.length / 50) }}</span><button class="refresh-control" :disabled="urlPage * 50 >= pages.length" @click="urlPage++">Next URLs</button></div></details>
        <section v-if="urlHistorySelection" class="report-panel" aria-label="URL observation history"><h3>URL history · {{ urlHistorySelection.url }}</h3><p class="report-caption">Each page shows up to 50 runs and retains one boundary row. Adjacent comparable observations are compared using stored source-property digests. Unknown fields, omitted observations, and missing pages never establish equality or removal. Imported reports are labeled; source pointers refer to the retained report.</p><p v-if="urlHistoryError" role="alert" class="form-error">{{ urlHistoryError }}</p><p v-if="urlHistoryBusy" role="status">Loading URL history…</p><div v-if="urlHistory" class="table-scroll"><table><thead><tr><th>Scan</th><th>Delivery / source</th><th>Observation</th><th>Change from prior run</th><th>Changed fields</th><th>Unknown fields</th><th>Source pointer</th></tr></thead><tbody><tr v-for="(row, i) in urlHistory.items" :key="row.delivery_id"><td>{{ stamp(row.scan_at) }}</td><td>{{ row.delivery_id }} · {{ row.ingestion_source === 'import' ? 'Imported report' : 'Worker delivery' }}</td><td>{{ label(row.evidence_state) }}{{ row.unknown_reason ? ' · ' + label(row.unknown_reason) : '' }}</td><td>{{ label(urlDeltas[i]?.state || 'not_observed') }}</td><td>{{ urlDeltas[i]?.changed.join(', ') || 'None observed' }}</td><td>{{ urlDeltas[i]?.unknown.join(', ') || 'None' }}</td><td>{{ row.source_locator || 'Unavailable' }}</td></tr></tbody></table><button v-if="urlHistory.has_more" class="refresh-control" :disabled="urlHistoryBusy" @click="loadUrlHistory(urlHistorySelection.entity_id, urlHistorySelection.url, true)">Load older URL history</button></div></section>
      </template>
      <details class="seo-history-table"><summary>Saved runs ({{ runs.length }} loaded)</summary><div class="table-scroll"><table><thead><tr><th>Scan time (UTC)</th><th>Coverage</th><th>URLs checked</th><th>Critical</th><th>Alerts</th><th>Warnings</th></tr></thead><tbody><tr v-for="run in runs" :key="run.delivery_id"><td><button class="refresh-control" @click="select(run.delivery_id)">{{ stamp(run.scan_at) }}</button></td><td>{{ run.summary.coverage_complete === true ? 'Complete' : run.summary.coverage_complete === false ? 'Incomplete' : 'Unknown' }}</td><td>{{ run.summary.pages.checked }}</td><td>{{ run.summary.severities.critical }}</td><td>{{ run.summary.severities.alert }}</td><td>{{ run.summary.severities.warning }}</td></tr></tbody></table></div></details>
    </template>
  </section>
</template>
